-- Data/Companions.lua: generated by tools/companions/build.py --lua. These
-- check its shape, so a bad generation fails tools/check.sh before it ships.
return function(test, H)
    local eq, ok, no = H.eq, H.ok, H.no

    test("the companion list has a sane shape", function()
        local w = H.World()
        local c = w:AddClient("Ola Nord")
        local data = c.ns.Companions
        ok(type(data) == "table" and type(data.build) == "number")
        ok(type(data.species) == "table", "generated, not the count-only stub")
        local n, counting = 0, 0
        for sid, e in pairs(data.species) do
            n = n + 1
            ok(type(sid) == "number" and sid > 0 and sid == math.floor(sid), "species id " .. tostring(sid))
            ok(type(e) == "table" and type(e.a) == "boolean", "entry " .. sid)
            if e.a then counting = counting + 1 end
            for _, tag in ipairs(e.t or {}) do
                ok(type(tag) == "string" and tag:find("^[a-z][a-z0-9_]*$"), "tag " .. tostring(tag) .. " on " .. sid)
            end
        end
        ok(n >= 50, "the journal has ~83 species, got " .. n)
        ok(counting > 0 and counting <= n)
        eq(c.ns.Pets:Total(), n, "the guild counter's total")
    end)

    test("the species the test client uses exist in it", function()
        local w = H.World()
        local c = w:AddClient("Ola Nord")
        for _, sid in ipairs({ 40, 46, 5159 }) do ok(c.ns.Companions.species[sid], "species " .. sid) end
        no(c.ns.Companions.species[99999])
    end)
end
